-- V3 20260617 N3 rebuild after N2 trigger-baseline semantic repair rollback
-- Scope: repaired-N2 N3 lineage only. Does not touch old-v1 artifacts unless explicitly added by operator.
-- Order: B2 metric -> source expansion minute facts -> source expansion control rows -> C1 -> A1 -> B1 -> base subscription.

BEGIN;

DO $$
DECLARE
  v_runs TEXT[] := ARRAY[
    'action_confirmation_projection_metric_20260617_until_1352__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1',
    'historical_closed_minute_source_expansion_20260617_until_1352_full_scope_missing__condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1',
    'market_data_subscription_20260617_full_scope_source_expansion__condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1',
    'today_minute_bar_1m_20260617_until_1352__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1',
    'previous_day_minute_preload_20260616_for_20260617__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1',
    'realtime_daily_snapshot_20260617_until_1352__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1',
    'market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_semantic_repair_v1'
  ];
  v_run TEXT;
  v_refs BIGINT;
BEGIN
  FOREACH v_run IN ARRAY v_runs LOOP
    SELECT
      (SELECT count(*) FROM common_event_outbox WHERE source_run_id = v_run)
      + (SELECT count(*) FROM common_event_inbox WHERE source_run_id = v_run)
      + (SELECT count(*) FROM common_event_consumer_checkpoint WHERE checkpoint_payload::text LIKE '%' || v_run || '%')
    INTO v_refs;
    IF v_refs <> 0 THEN
      RAISE EXCEPTION 'rollback blocked: event/checkpoint refs exist for % refs=%', v_run, v_refs;
    END IF;
  END LOOP;
END $$;

